// B1 ampliado (b1-part7.ts): lectura, práctica, vocabulario temático y escucha larga de las 5 unidades nuevas (compras y vivienda, medio ambiente, medios, relaciones y estudio).
// Todo es «bonus». La práctica no enseña vocabulario nuevo; el vocabulario temático usa palabras que antes eran solo del entrenador.

import type { Lesson, ListenQuestion, Vocab, HandExercise } from "../curriculum.ts";
import type { FreePrompt } from "./free-prompts.ts";
import { reading } from "./readings.ts";
import { practice, cz, qz } from "./practice-a2.ts";

type L = ["f" | "m", string, string, string];

const thema = (
  title: string, icon: string, goal: string, intro: string[], summary: string[], vocab: Vocab[], exercises: HandExercise[],
  dTitle: string, setting: string, lines: L[], questions: ListenQuestion[],
): Lesson => ({
  id: "wortschatz",
  title: `Vocabulario: ${title}`,
  goal, icon, bonus: true, intro, summary, vocab, exercises,
  dialogue: { title: dTitle, setting, lines: lines.map(([who, name, de, es]) => ({ who, name, de, es })), questions },
});

const listening = (title: string, goal: string, dTitle: string, setting: string, lines: L[], questions: ListenQuestion[]): Lesson => ({
  id: "escucha-larga",
  title: `Escucha larga: ${title}`,
  goal,
  icon: "🎧",
  bonus: true,
  vocab: [],
  exercises: [],
  dialogue: { title: dTitle, setting, lines: lines.map(([who, name, de, es]) => ({ who, name, de, es })), questions },
});

